const cfgMsg = (cfg, k) => String(cfg[k] ?? '').replace(/\\n/g, '\n');
const juntar = (...partes) => partes.map(p => String(p ?? '').trim()).filter(Boolean).join('\n\n');

const body = $('Webhook Vocero').first().json.body || {};
const m = body.message || {};
const s = $('Carregar sessão').first().json;
const cfg = s.config || {};
let ctx = s.contexto || {};
let estado = s.estado || 'INICIO';
let tentativas = s.tentativas || 0;
const msgs = [];
let chamar = 'nenhuma';
let transbordo = false;
let nota = null;

// Telefone do remetente — a API aceita qualquer formato; mandamos 55+DDD+9+número
let tel = String(body.contact?.phone || '').replace(/\D/g, '');
if (tel.length === 12 && tel.startsWith('55')) tel = tel.slice(0, 4) + '9' + tel.slice(4);

const timeoutMin = Number(cfg.timeout_sessao_min || 60);
const idadeMin = (Date.now() - new Date(s.updated_at).getTime()) / 60000;
if (s.nova !== true && idadeMin > timeoutMin) estado = 'INICIO';
if (['FIM', 'HUMANO'].includes(estado)) estado = 'INICIO';

const texto = String(m.text || '').trim().toLowerCase();
const opcao = texto.replace(/^0+(?=\d)/, '');
const midia = m.media || null;
const mime = String(midia?.mimeType || '').toLowerCase();
// Mídia ainda em recuperação (available: false) entra na janela: é baixada depois.
const isArquivo = ['image', 'document'].includes(m.type) && !!midia && (midia.available === false ||
  /^(image\/(jpeg|png|webp|tiff)|application\/pdf)$/.test(mime));

if (estado !== 'INICIO' && ['menu', '0'].includes(texto)) estado = 'VOLTAR_MENU';

if (estado === 'INICIO') {
  ctx = {}; tentativas = 0;
  msgs.push(cfgMsg(cfg, 'msg_saudacao'), cfgMsg(cfg, 'msg_menu'));
  estado = 'MENU';
} else if (estado === 'VOLTAR_MENU') {
  ctx = {}; tentativas = 0;
  msgs.push(cfgMsg(cfg, 'msg_menu'));
  estado = 'MENU';
} else if (estado === 'MENU') {
  if (opcao === '1') {
    ctx = { arquivos: [] }; tentativas = 0;
    msgs.push(cfgMsg(cfg, 'msg_pedir_damdfe'));
    estado = 'AGUARDANDO_DAMDFE';
  } else if (opcao === '2') {
    msgs.push(cfgMsg(cfg, 'msg_pedir_localizacao'));
    estado = 'CARGAS_AGUARDANDO_LOCAL';
  } else {
    msgs.push(cfgMsg(cfg, 'msg_opcao_invalida'), cfgMsg(cfg, 'msg_menu'));
  }
} else if (estado === 'AGUARDANDO_DAMDFE') {
  if (isArquivo) chamar = 'aguardar_arquivos';
  else msgs.push(cfgMsg(cfg, 'msg_pedir_arquivo'));
} else if (estado === 'VALIDANDO') {
  msgs.push(cfgMsg(cfg, 'msg_aguarde'));
} else if (estado === 'CARGAS_AGUARDANDO_LOCAL') {
  // Fluxo 2 ainda não definido: guarda a localização e passa para o atendente
  ctx.localizacao = m.type === 'location' && m.location ? m.location : { texto: m.text || '' };
  msgs.push(cfgMsg(cfg, 'msg_cargas_recebido'));
  transbordo = true;
  nota = 'Bot MDF-e: motorista pediu cargas na região. Localização: ' + JSON.stringify(ctx.localizacao);
  estado = 'HUMANO';
}

return [{ json: {
  sessaoId: s.id,
  conversationId: body.conversationId,
  messageId: m.id,
  telefone: tel,
  estado, contexto: ctx, tentativas,
  texto: juntar(...msgs),
  transbordo, nota, chamar,
  registro: null,
  config: cfg,
} }];

const cfg = $('Decidir').first().json.config;
const baseUrl = String(cfg.api_mdfe_base_url || '').replace(/\/+$/, '');
const st = $getWorkflowStaticData('global');
const req = opts => this.helpers.httpRequest({ returnFullResponse: true, ignoreHttpStatusErrors: true,
  json: false, timeout: 30000, ...opts });
const parse = b => { if (b == null) return null; if (typeof b === 'string') { try { return JSON.parse(b); } catch { return { raw: b.slice(0, 500) }; } } return b; };
const agora = () => Date.now();
const guardar = (j, comRefresh) => {
  st.mdfeAccess = j.access_token; st.mdfeAccessExp = agora() + 29 * 60 * 1000;
  if (comRefresh && j.refresh_token) { st.mdfeRefresh = j.refresh_token; st.mdfeRefreshExp = agora() + 7 * 24 * 3600 * 1000 - 3600 * 1000; }
};
async function login() {
  const user = $env.MDFE_API_USER, pass = $env.MDFE_API_PASS;
  if (!user || !pass) throw new Error('sem_credencial');
  const r = await req({ method: 'POST', url: baseUrl + '/auth/login',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'username=' + encodeURIComponent(user) + '&password=' + encodeURIComponent(pass) });
  if (r.statusCode === 401) throw new Error('login_401');
  if (r.statusCode !== 200) throw new Error('login_http_' + r.statusCode);
  guardar(parse(r.body), true);
}
async function refresh() {
  if (!st.mdfeRefresh || (st.mdfeRefreshExp || 0) < agora()) return false;
  const r = await req({ method: 'POST', url: baseUrl + '/auth/refresh',
    headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ refresh_token: st.mdfeRefresh }) });
  if (r.statusCode !== 200) return false;
  guardar(parse(r.body), false);
  return true;
}
async function garantirToken() {
  if (st.mdfeAccess && (st.mdfeAccessExp || 0) > agora() + 60000) return;
  if (await refresh()) return;
  await login();
}

const d = $('Decidir').first().json;
const ids = $('Listar arquivos').all().map(i => i.json.messageId);
const baixados = $input.all();
const IMG = /^image\/(jpeg|png|webp|tiff)$/;
const ext = { 'application/pdf': '.pdf', 'image/jpeg': '.jpg', 'image/png': '.png', 'image/webp': '.webp', 'image/tiff': '.tif' };
const midias = [];
for (let i = 0; i < baixados.length; i++) {
  const bin = baixados[i].binary?.data;
  if (!bin) continue;
  const mime = String(bin.mimeType || '').split(';')[0].trim().toLowerCase();
  if (mime !== 'application/pdf' && !IMG.test(mime)) continue;
  const fileName = String(bin.fileName && /\.\w+$/.test(bin.fileName) ? bin.fileName : 'damdfe_' + ids[i] + ext[mime]).replace(/["\r\n]/g, '');
  midias.push({ id: ids[i], mime, bin: { ...bin, mimeType: mime, fileName } });
}
// Regra da API: 1 PDF ou de 1 a 3 imagens, sem misturar
const pdf = midias.find(m => m.mime === 'application/pdf');
const sel = pdf ? [pdf] : midias.slice(0, 3);
const out = { arquivosIds: sel.map(m => m.id), http: null, resposta: null, falha: null, baseUrl, telefone: d.telefone, qtd: sel.length };
if (sel.length === 0) { out.falha = 'sem_midia'; return [{ json: out }]; }
try {
  await garantirToken();
} catch (e) {
  out.falha = String((e && e.message) || e).slice(0, 200);
  return [{ json: out }];
}
// Os bytes não passam por aqui: o nó Code só repassa as referências dos arquivos.
const binary = {};
sel.forEach((m, i) => { binary['f' + i] = m.bin; });
return [{ json: { ...out, token: st.mdfeAccess }, binary }];

const cfg = $('Decidir').first().json.config;
const baseUrl = String(cfg.api_mdfe_base_url || '').replace(/\/+$/, '');
const st = $getWorkflowStaticData('global');
const req = opts => this.helpers.httpRequest({ returnFullResponse: true, ignoreHttpStatusErrors: true,
  json: false, timeout: 30000, ...opts });
const parse = b => { if (b == null) return null; if (typeof b === 'string') { try { return JSON.parse(b); } catch { return { raw: b.slice(0, 500) }; } } return b; };
const agora = () => Date.now();
const guardar = (j, comRefresh) => {
  st.mdfeAccess = j.access_token; st.mdfeAccessExp = agora() + 29 * 60 * 1000;
  if (comRefresh && j.refresh_token) { st.mdfeRefresh = j.refresh_token; st.mdfeRefreshExp = agora() + 7 * 24 * 3600 * 1000 - 3600 * 1000; }
};
async function login() {
  const user = $env.MDFE_API_USER, pass = $env.MDFE_API_PASS;
  if (!user || !pass) throw new Error('sem_credencial');
  const r = await req({ method: 'POST', url: baseUrl + '/auth/login',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'username=' + encodeURIComponent(user) + '&password=' + encodeURIComponent(pass) });
  if (r.statusCode === 401) throw new Error('login_401');
  if (r.statusCode !== 200) throw new Error('login_http_' + r.statusCode);
  guardar(parse(r.body), true);
}
async function refresh() {
  if (!st.mdfeRefresh || (st.mdfeRefreshExp || 0) < agora()) return false;
  const r = await req({ method: 'POST', url: baseUrl + '/auth/refresh',
    headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ refresh_token: st.mdfeRefresh }) });
  if (r.statusCode !== 200) return false;
  guardar(parse(r.body), false);
  return true;
}
async function garantirToken() {
  if (st.mdfeAccess && (st.mdfeAccessExp || 0) > agora() + 60000) return;
  if (await refresh()) return;
  await login();
}

const prep = $('Preparar envio').first();
const r = $input.first().json;
const status = r.statusCode;
const out = { arquivosIds: prep.json.arquivosIds, http: status ?? null, resposta: parse(r.body), falha: null };
if (!status) return [{ json: { ...out, resposta: null, falha: 'rede: ' + String(r.error?.message || r.error || 'sem resposta').slice(0, 180) } }];

const repetir = token => [{ json: { ...prep.json, token, repetir: true }, binary: prep.binary }];
// Até 2 repetições por envio ($runIndex conta as passagens por este nó)
if ($runIndex < 2) {
  if (status === 401) {
    try {
      st.mdfeAccessExp = 0;
      if (!(await refresh())) await login();
      return repetir(st.mdfeAccess);
    } catch (e) {
      return [{ json: { ...out, falha: String((e && e.message) || e).slice(0, 200) } }];
    }
  }
  if (status === 429 || status === 503) {
    const ra = Number((r.headers || {})['retry-after']) || 30;
    await new Promise(ok => setTimeout(ok, Math.min(ra, 60) * 1000));
    return repetir(prep.json.token);
  }
}
return [{ json: out }];

const cfgMsg = (cfg, k) => String(cfg[k] ?? '').replace(/\\n/g, '\n');
const juntar = (...partes) => partes.map(p => String(p ?? '').trim()).filter(Boolean).join('\n\n');

const d = $('Decidir').first().json;
const sessao = $('Marcar validando').first().json;
const api = $input.first().json;
const cfg = d.config;
const ctx = { ...(sessao.contexto || {}), arquivos: [] };
let tentativas = sessao.tentativas || 0;
const max = Number(cfg.max_tentativas_documento || 3);
const out = { ...d, chamar: 'nenhuma', transbordo: false, nota: null };
const r = api.resposta || {};

const REENVIO = ['CHAVE_ILEGIVEL', 'DOCUMENTO_NAO_E_MDFE', 'CTE_DIVERGENTE', 'EMPRESA_DIVERGENTE'];
let status = r.status || null, codigo = r.codigo || null;
const notaOperacao = c => `Bot MDF-e: código ${c || '-'}, protocolo ${r.protocolo || '-'}, chave ${r.mdfe?.chave || '-'}, telefone ${d.telefone}`;
const aguardarDeNovo = (texto) => { out.texto = texto; out.estado = 'AGUARDANDO_DAMDFE'; };
const contarTentativa = (texto) => {
  tentativas += 1;
  if (tentativas >= max) {
    out.texto = juntar(texto, cfgMsg(cfg, 'msg_transbordo'));
    out.transbordo = true; out.nota = notaOperacao(codigo); out.estado = 'HUMANO';
  } else aguardarDeNovo(texto);
};
const operacao = (texto) => {
  out.texto = juntar(texto, cfgMsg(cfg, 'msg_operacao'));
  out.transbordo = true; out.nota = notaOperacao(codigo); out.estado = 'HUMANO';
};

if (api.falha === 'sem_midia') { status = 'falha_local'; codigo = 'SEM_MIDIA'; aguardarDeNovo(cfgMsg(cfg, 'msg_pedir_arquivo')); }
else if (api.falha === 'arquivo_grande' || api.http === 413) { status = status || 'falha_local'; codigo = codigo || 'ARQUIVO_GRANDE'; aguardarDeNovo(cfgMsg(cfg, 'msg_arquivo_grande')); }
else if (api.falha) { status = 'falha_local'; codigo = api.falha; out.texto = cfgMsg(cfg, 'msg_erro_tecnico'); out.transbordo = true; out.nota = 'Bot MDF-e: falha ao chamar a API (' + api.falha + ')' + (api.falha === 'login_401' ? ' — senha do usuário da API mudou' : ''); out.estado = 'HUMANO'; }
else if (api.http === 422) { codigo = 'HTTP_422'; contarTentativa(cfgMsg(cfg, 'msg_arquivo_ilegivel')); }
else if (api.http === 429 || api.http === 503) { codigo = 'HTTP_' + api.http; out.texto = cfgMsg(cfg, 'msg_indisponivel'); out.estado = 'FIM'; }
else if (api.http !== 200) { codigo = 'HTTP_' + api.http; out.texto = cfgMsg(cfg, 'msg_erro_tecnico'); out.transbordo = true; out.nota = `Bot MDF-e: API devolveu HTTP ${api.http}: ${r.detail || ''}`; out.estado = 'HUMANO'; }
else if (status === 'encerrado' || status === 'validado') {
  tentativas = 0;
  aguardarDeNovo(juntar(r.mensagem, cfgMsg(cfg, 'msg_pos_encerrado')));
}
else if (status === 'divergente') {
  if (REENVIO.includes(codigo)) contarTentativa(juntar(r.mensagem, cfgMsg(cfg, 'msg_reenviar')));
  else operacao(r.mensagem);
}
else if (status === 'erro') {
  if (codigo === 'ENCERRAMENTO_EM_PROCESSAMENTO') aguardarDeNovo(juntar(r.mensagem, cfgMsg(cfg, 'msg_em_processamento')));
  else operacao(r.mensagem);
}
else { codigo = codigo || 'RESPOSTA_INESPERADA'; out.texto = cfgMsg(cfg, 'msg_erro_tecnico'); out.transbordo = true; out.nota = 'Bot MDF-e: resposta fora do contrato da API'; out.estado = 'HUMANO'; }

out.contexto = ctx;
out.tentativas = tentativas;
out.registro = {
  conversation_id: d.conversationId, telefone: d.telefone,
  http_status: api.http, status, codigo,
  protocolo: r.protocolo ?? null, chave_mdfe: r.mdfe?.chave ?? null,
  numero_mdfe: r.mdfe?.numero != null ? String(r.mdfe.numero) : null,
  mensagem: r.mensagem ?? r.detail ?? null,
  retorno_api: api.resposta ?? null,
  encerrado_em: status === 'encerrado' ? new Date().toISOString() : null,
  arquivos: api.arquivosIds || [],
};
return [{ json: out }];
